{
  "items": [
    {
      "name": "Ideal.mem_span_singleton'",
      "type": " {α : Type u} [Semiring α] {x y : α} : x ∈ Ideal.span {y} ↔ ∃ a, a * y = x",
      "module": "Mathlib.RingTheory.Ideal.Span"
    },
    {
      "name": "Ideal.span_eq_top_iff_finite",
      "type": " {α : Type u} [Semiring α] (s : Set α) : Ideal.span s = ⊤ ↔ ∃ s', ↑s' ⊆ s ∧ Ideal.span ↑s' = ⊤",
      "module": "Mathlib.RingTheory.Ideal.Span"
    },
    {
      "name": "Ideal.mem_span_pair",
      "type": " {α : Type u} [Semiring α] {x y z : α} : z ∈ Ideal.span {x, y} ↔ ∃ a b, a * x + b * y = z",
      "module": "Mathlib.RingTheory.Ideal.Span"
    },
    {
      "name": "Ideal.mem_span_insert",
      "type": " {α : Type u} [Semiring α] {s : Set α} {x y : α} : x ∈ Ideal.span (insert y s) ↔ ∃ a, ∃ z ∈ Ideal.span s, x = a * y + z",
      "module": "Mathlib.RingTheory.Ideal.Span"
    },
    {
      "name": "Ideal.mem_span_insert'",
      "type": " {α : Type u} [Ring α] (x y : α) (s : Set α) : x ∈ Ideal.span (insert y s) ↔ ∃ a, x + a * y ∈ Ideal.span s",
      "module": "Mathlib.RingTheory.Ideal.Span"
    }
  ]
}
